import math

class SensorNode:
    def __init__(self, node_id, x, y, range_r):
        self.id = node_id
        self.x = x
        self.y = y
        self.range_r = range_r
        self.neighbours = []

    def discover_neighbours(self, all_nodes):
        for node in all_nodes:
            if node.id != self.id:
                distance = math.sqrt((self.x - node.x)**2 + (self.y - node.y)**2)
                if distance <= self.range_r:
                    self.neighbours.append(node.id)

