import random

class TemperatureAgent:
    def __init__(self, agent_id, threshold=30.0):
        self.agent_id = agent_id
        self.threshold = threshold
        self.state = "NORMAL"

    def perceive_and_decide(self, current_temp):
        """Reasoning engine of the software agent"""
        print(f"[Agent {self.agent_id}] Observed temperature: {current_temp}°C")
        if current_temp > self.threshold:
            self.state = "ALERT"
            return self.act_cool_down()
        else:
            self.state = "NORMAL"
            return "Status OK. Maintaining monitoring."

    def act_cool_down(self):
        return f"[ACTION] Agent {self.agent_id} triggered emergency cooling actuators!"

# Simulating agent execution loop
agent = TemperatureAgent("Zone-A-Node")
for _ in range(3):
    simulated_temp = random.uniform(25.0, 35.0)
    print(agent.perceive_and_decide(simulated_temp))
